// SummarizeDeliveryFailures counts failed and retrying attempts ... grouped by
// the exact stored failure_reason text. Groups sort by attempt count
// descending, ties by the reason text ascending.
func (s *Store) SummarizeDeliveryFailures(ctx context.Context, query delivery.SummaryQuery) (FailureSummary, error) {
	clauses := []string{
		"channel = ?",
		"occurred_at >= ?",
		"occurred_at < ?",
		"status IN (?, ?)",
		"failure_reason != ''",
	}
